-- Purpose: bulk-load the MySQL-ready CSV generated by python/02_parquet_to_mysql.py.
-- Prerequisite: run sql/00_schema.sql and confirm events contains zero rows.
-- Important: replace the absolute path below if the repository is cloned elsewhere.
-- Do not rerun this statement unless the target table has been checked for partial or existing data.

SHOW GLOBAL VARIABLES LIKE 'local_infile';

SELECT COUNT(*) AS rows_before_load
FROM rees46_funnel_analysis.events;

LOAD DATA LOCAL INFILE
'E:/GitHub Projects/rees46-funnel-analysis/data/processed/clean_data/clean_data_mysql.csv'
INTO TABLE rees46_funnel_analysis.events
CHARACTER SET utf8mb4
FIELDS TERMINATED BY ','
OPTIONALLY ENCLOSED BY '"'
LINES TERMINATED BY '\r\n'
IGNORE 1 LINES
(
    event_time,
    event_type,
    product_id,
    category_id,
    price,
    user_id,
    @user_session
)
SET user_session = NULLIF(@user_session, '\\N');

-- Run immediately after LOAD DATA in the same connection so warnings are not lost.
SHOW WARNINGS LIMIT 20;
